          <TableRow key={id} aria-selected={sel === id} onClick={() => setSel(id)} style={{ cursor: "pointer" }}>
            <TableCell>#{id}</TableCell><TableCell>{who}</TableCell><TableCell>{total}</TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

